'use strict';

// MODULES //

var path = require( 'node:path' );
var readFile = require( 'node:fs/promises' ).readFile;
var assertCanonicalGzip = require( '@data-apis/record/assert-canonical-gzip' );
var indexKey = require( '@data-apis/record/index-key' );
var parseGzipEnvelope = require( '@data-apis/record/parse-gzip-envelope' );
var parseRecordPath = require( '@data-apis/record/parse-path' );
var filenameTimestamp = require( '@data-apis/record/filename-timestamp' );
var normalizeTimestamp = require( '@data-apis/report/normalize-timestamp' );
var validateEnvelope = require( '@data-apis/record/validate-envelope' );
var validateIndexRow = require( '@data-apis/record/validate-index-row' );
var getSource = require( '@data-apis/registry/get-source' );
var assertRegistryHistory = require( '@data-apis/repository/assert-registry-history' );
var buildState = require( '@data-apis/repository/build-state' );
var loadIndex = require( '@data-apis/repository/load-index' );
var walkRecordPaths = require( '@data-apis/repository/walk-record-paths' );


// FUNCTIONS //

/**
* Validates path/index coverage and uniqueness.
*
* @private
* @param {Object} index - data index
* @param {Array} paths - record paths
*/
function validateRows( index, paths ) {
	var pathSet = new Set( paths );
	var rowPaths = new Set();
	var keys = new Set();

	index.records.forEach( function validateRow( row ) {
		var key;
		var parsed;
		var timestamp;

		parsed = parseRecordPath( row.path );
		timestamp = normalizeTimestamp( row.timestamp );
		if ( row.library_id !== parsed.libraryId || row.source_id !== parsed.sourceId || timestamp !== row.timestamp || filenameTimestamp( timestamp ) !== parsed.filenameTimestamp || row.report_sha256 !== parsed.reportSha256 ) {
			throw new Error( 'Index metadata does not agree with path: ' + row.path );
		}
		if ( rowPaths.has( row.path ) ) {
			throw new Error( 'Duplicate index path: ' + row.path );
		}
		rowPaths.add( row.path );
		key = indexKey( row );
		if ( keys.has( key ) ) {
			throw new Error( 'Duplicate index key for path: ' + row.path );
		}
		keys.add( key );
		if ( !pathSet.has( row.path ) ) {
			throw new Error( 'Index path does not exist: ' + row.path );
		}
	} );
	if ( rowPaths.size !== pathSet.size ) {
		throw new Error( 'Stored record is missing from data/index.json: ' + paths.find( function missing( value ) {
			return !rowPaths.has( value );
		} ) );
	}
}


// MAIN //

/**
* Validates repository data and optionally all compressed records.
*
* @param {Object} options - validation options
* @param {string} options.dataDirectory - data directory
* @param {Object} [options.registry] - registry
* @param {boolean} [options.all=false] - whether to validate every record
* @returns {Promise<Object>} index, paths, and state
*/
async function validateRepository( options ) {
	var index = await loadIndex( options.dataDirectory );
	var paths = await walkRecordPaths( options.dataDirectory );
	var validateOptions;
	var expectedName;
	var envelope;
	var lookup;
	var bytes;
	var row;

	validateRows( index, paths );
	if ( options.registry ) {
		assertRegistryHistory( options.registry, index );
	}
	if ( options.all ) {
		for ( row of index.records ) {
			bytes = await readFile( path.join( options.dataDirectory, ...row.path.split( '/' ) ) );
			envelope = parseGzipEnvelope( bytes );
			lookup = options.registry ? getSource( options.registry, row.library_id, row.source_id ) : {};
			expectedName = lookup.library ? ( lookup.library.report_name || lookup.library.id ) : undefined;
			validateOptions = { 'expectedName': expectedName };

			validateEnvelope( envelope, row.path, validateOptions );
			validateIndexRow( row, envelope, row.path, validateOptions );
			assertCanonicalGzip( bytes, envelope );
		}
	}
	return {
		'index': index,
		'paths': paths,
		'state': buildState( index )
	};
}


// EXPORTS //

module.exports = validateRepository;
